package carrier

// Notify reports the approaching deadline over the lifecycle-
// channel of the pod, whose compound spelling wraps immediately after
// its hyphen. The site below it is the second of this carrier, so an
// enumeration that read the wrap as no site at all would write the
// identifier resolved here at the site after it.
func Notify() bool { return true }

// Warn reports the same deadline over the lifecycle channel in the
// spelling that stands on one line.
func Warn() bool { return true }
